"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["7028"],{18031(e){e.exports=JSON.parse('{"id":"F339","slug":"barrier-option-payoff","name":"Barrier Option Payoff","subject":"Derivatives","section":"Derivatives","topic":"Exotic options","level":"Intermediate","aliases":["knock-out option","knock-in option","up and out call","down and in put"],"formula":{"latex":"\\\\text{Up-and-out call}=\\\\begin{cases}0 & \\\\max(S_{t})\\\\ge B\\\\\\\\ \\\\max(S_{T}-K,0) & \\\\text{otherwise}\\\\end{cases}","also":[],"text":"An up-and-out call pays max(ST - K, 0) only if the price never touched the barrier B; an up-and-in call pays it only if the barrier was touched"},"symbols":[{"symbol":"B","meaning":"Barrier level that switches the option off (knock-out) or on (knock-in)","unit":"money"},{"symbol":"S_t","meaning":"Price on each observation date","unit":"money"},{"symbol":"S_T","meaning":"Price at expiry","unit":"money"},{"symbol":"K","meaning":"Strike","unit":"money"}],"when_to_use":"Use it to see how a barrier changes a call\'s payoff. Knock-out options are cheaper than standard options because they can disappear. A knock-in plus a knock-out with the same barrier and strike equals one ordinary option.","worked_example":{"problem":"The prices on observation dates are 100, 104, 98, 106, 110 and 108. A call has a strike of 100 and a barrier of 115 (up-and-out), and another has a barrier of 109 (up-and-out). What does each pay?","inputs":{"p":[100,104,98,106,110,108],"k":100,"b1":115,"b2":109},"steps":[{"label":"Highest price reached","working":"max([100, 104, 98, 106, 110, 108])","value":"110.00"},{"label":"Payoff with the first barrier","working":"0 if 110>=115 else max([100, 104, 98, 106, 110, 108][-1]-100, 0)","value":"8.00"},{"label":"Payoff with the second barrier","working":"0 if 110>=109 else max([100, 104, 98, 106, 110, 108][-1]-100, 0)","value":"0.00"}],"answer":"The highest price was 110.00. The option with a barrier of 115 never reached it, so it pays 8.00. The option with a barrier of 109 was knocked out because the price reached 110, so it pays 0.00."},"calculator":{"available":true,"inputs":[{"id":"p","label":"Prices on the observation dates","unit":"money","type":"list","default":[100,104,98,106,110,108],"hint":""},{"id":"k","label":"Strike price","unit":"money","type":"number","default":100,"hint":""},{"id":"b1","label":"First barrier (up-and-out)","unit":"money","type":"number","default":115,"hint":""},{"id":"b2","label":"Second barrier (up-and-out)","unit":"money","type":"number","default":109,"hint":""}],"checks":[{"expr":"count(p)>=2","message":"Enter at least two prices."}],"steps":[{"id":"hi","label":"Highest price reached","expr":"max(p)","format":"money"},{"id":"pay1","label":"Payoff with the first barrier","expr":"0 if hi>=b1 else max(p[-1]-k, 0)","format":"money"},{"id":"pay2","label":"Payoff with the second barrier","expr":"0 if hi>=b2 else max(p[-1]-k, 0)","format":"money"}],"results":["pay1","pay2"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"hi":110,"pay1":8,"pay2":0}},"finder":{"finds":"What a knock-out call pays","needs":"Price path, strike, barrier"},"related":[{"slug":"asian-option-payoff","name":"Asian Option Payoff"},{"slug":"option-payoffs","name":"Call and Put Payoffs and Profit"}],"related_ids":["F338","F325"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Up-and-out\xa0call</mtext><mo>=</mo><mrow><mo fence=\\"true\\">{</mo><mtable rowspacing=\\"0.36em\\" columnalign=\\"left left\\" columnspacing=\\"1em\\"><mtr><mtd><mstyle scriptlevel=\\"0\\" displaystyle=\\"false\\"><mn>0</mn></mstyle></mtd><mtd><mstyle scriptlevel=\\"0\\" displaystyle=\\"false\\"><mrow><mi>max</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><msub><mi>S</mi><mi>t</mi></msub><mo stretchy=\\"false\\">)</mo><mo>\u2265</mo><mi>B</mi></mrow></mstyle></mtd></mtr><mtr><mtd><mstyle scriptlevel=\\"0\\" displaystyle=\\"false\\"><mrow><mi>max</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><msub><mi>S</mi><mi>T</mi></msub><mo>\u2212</mo><mi>K</mi><mo separator=\\"true\\">,</mo><mn>0</mn><mo stretchy=\\"false\\">)</mo></mrow></mstyle></mtd><mtd><mstyle scriptlevel=\\"0\\" displaystyle=\\"false\\"><mtext>otherwise</mtext></mstyle></mtd></mtr></mtable></mrow></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Up-and-out call}=\\\\begin{cases}0 &amp; \\\\max(S_{t})\\\\ge B\\\\\\\\ \\\\max(S_{T}-K,0) &amp; \\\\text{otherwise}\\\\end{cases}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"irrbb-eve-nii","name":"Banking Book Interest Rate Risk: EVE and NII"},"next":{"slug":"basel-capital-buffers","name":"Basel III Capital Requirement Stack and Buffers"},"lesson":null,"total":522}')}}]);